args => {
  const {
    listenersEnabled,
    clipboardEnabled
  } = args;
  // Patch navigator.clipboard before React renders — hasClipboard is evaluated per render in AiChatBubble,
  // so this must execute before the component tree mounts (which it does, since the story function runs first).
  Object.defineProperty(navigator, 'clipboard', {
    value: clipboardEnabled ? nativeClipboard : undefined,
    configurable: true
  });
  return <div style={STORY_WRAPPER}>
      <div style={STORY_INNER}>
        <style>{STORY_MAIN_CSS}</style>
        <header>
          <h1 className="sol-screenreader-only">AI Assistant action buttons</h1>
        </header>
        <main>
          <SOLAiAssistant open messages={buildActionButtonMessages(args)} onMessageAction={e => console.log('messageAction', e)} onFeedbackChange={listenersEnabled ? e => console.log('feedbackChange', e) : undefined} onRetryRequested={listenersEnabled ? id => console.log('retryRequested', id) : undefined} />
        </main>
      </div>
    </div>;
}

{
  render: function Render() {
    const [open, setOpen] = useState(true);
    const [responding, setResponding] = useState(false);
    const [messages, setMessages] = useState<SolAiMessage[]>([{
      id: 'u1',
      role: 'user',
      content: 'Show me the top account.'
    }, {
      id: 'a1',
      role: 'ai',
      content: {
        title: 'Acme Corp',
        stats: ['ARR $500K', 'Renewal in 30 days', 'NPS 72'],
        tag: 'At Risk',
        tagCritical: true,
        showIcon: true
      }
    }, {
      id: 'u2',
      role: 'user',
      content: 'What about Globex?'
    }, {
      id: 'a2',
      role: 'ai',
      content: {
        title: 'Globex Inc',
        stats: ['ARR $1.2M', 'Renewal in 180 days', 'NPS 85'],
        note: 'Champion recently promoted to VP — strong expansion signal.',
        tag: 'Healthy',
        tagColor: 'var(--sol-color-text-status-success)'
      }
    }, {
      id: 'u3',
      role: 'user',
      content: 'Any notes on Acme?'
    }, {
      id: 'a3',
      role: 'ai',
      content: 'Last call was on July 15. Champion confirmed budget approved.'
    }]);
    return <div style={STORY_WRAPPER}>
        <div style={STORY_INNER}>
          <style>{STORY_MAIN_CSS}</style>
          <main>
            <SOLAiAssistant open={open} onOpenChange={setOpen} userName="Alex" messages={messages} messageFormatter={SmartFormatter} responding={responding} stopEnabled onStopRequested={() => setResponding(false)} onPromptSubmit={text => {
            setResponding(true);
            setMessages(prev => [...prev, {
              id: `u-${prev.length}`,
              role: 'user',
              content: text
            }, {
              id: `a-${prev.length}`,
              role: 'ai',
              stream: fakeStream('This is a simulated streaming response.', () => setResponding(false))
            }]);
          }} onFeedbackChange={e => console.log('feedbackChange', e)} onRetryRequested={id => console.log('retryRequested', id)} />
          </main>
        </div>
      </div>;
  }
}

({
  variant,
  maxLength,
  promptShortcut,
  open: openArg,
  responding: respondingArg
}) => {
  const [open, setOpen] = useState(openArg);
  const [responding, setResponding] = useState(respondingArg);
  useEffect(() => setOpen(openArg), [openArg]);
  const [messages, setMessages] = useState<SolAiMessage[]>(messagesByVariant[variant]);

  // Reset when the Controls variant or responding arg changes so the story reflects the new selection.
  useEffect(() => {
    setMessages(messagesByVariant[variant]);
    setResponding(respondingArg);
  }, [variant, respondingArg]);
  return <div style={STORY_WRAPPER}>
      <div style={STORY_INNER}>
        <style>{STORY_MAIN_CSS}</style>
        <header>
          <h1 className="sol-screenreader-only">AI Assistant default conversation</h1>
        </header>
        <main>
          <SOLAiAssistant open={open} onOpenChange={setOpen} userName="Alex" messages={messages} maxLength={maxLength} promptShortcut={promptShortcut} suggestions={['Create an AI Agent', 'See what has changed since yesterday', 'How can I manually configure AI Agents?']} disclaimerMessage="AI assistant can make mistakes. Double-check responses." moreActions={[{
          id: 'clear',
          label: 'Clear conversation',
          icon: 'sol-delete'
        }, {
          id: 'feedback',
          label: 'Send feedback',
          icon: 'sol-thumbs-up'
        }]} stopEnabled responding={responding} onStopRequested={() => setResponding(false)} onPromptSubmit={text => {
          setResponding(true);
          setMessages(prev => [...prev, {
            id: `u-${prev.length}`,
            role: 'user',
            content: text
          }, {
            id: `a-${prev.length}`,
            role: 'ai',
            stream: fakeStream('This is a simulated streaming response.', () => setResponding(false))
          }]);
        }} onMessageAction={e => console.log('messageAction', e)} onOpened={() => console.log('opened')} onClosed={() => console.log('closed')} onFeedbackChange={e => console.log('feedbackChange', e)} onRetryRequested={id => console.log('retryRequested', id)} />
        </main>
      </div>
    </div>;
}

{
  args: {
    title: 'AI Assistant',
    welcomeMessage: '',
    disclaimerMessage: 'AI assistant can make mistakes. Double-check responses.',
    width: '',
    resizable: true,
    userName: 'Alex',
    stopEnabled: true
  },
  // The meta hides these controls for the other stories; show them for this one.
  argTypes: {
    title: {
      control: 'text',
      description: 'Header title',
      table: {
        disable: false
      }
    },
    welcomeMessage: {
      control: 'text',
      description: 'Second greeting line; falls back to the translated "How can I help?" when empty',
      table: {
        disable: false
      }
    },
    disclaimerMessage: {
      control: 'text',
      description: 'Disclaimer under the prompt field; falls back to the translated default when empty',
      table: {
        disable: false
      }
    },
    width: {
      control: 'text',
      description: 'Panel width as a CSS length (e.g. 30rem); empty uses the default width',
      table: {
        disable: false
      }
    },
    resizable: {
      control: 'boolean',
      description: 'Shows the drag handle that resizes the panel',
      table: {
        disable: false
      }
    },
    userName: {
      control: 'text',
      description: 'Name used in the greeting ("Hi <name>,")',
      table: {
        disable: false
      }
    },
    stopEnabled: {
      control: 'boolean',
      description: 'Shows a Stop button instead of Send while a response is streaming',
      table: {
        disable: false
      }
    }
  },
  render: function Render(args) {
    const [open, setOpen] = useState(true);
    const [responding, setResponding] = useState(false);
    const [messages, setMessages] = useState<SolAiMessage[]>([]);
    return <div style={{
      width: '100%',
      height: 600,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: '#F3F4F6'
    }}>
        <div style={{
        position: 'relative',
        display: 'flex',
        height: '100%',
        width: '100%',
        maxWidth: 600
      }}>
          <style>{STORY_MAIN_CSS}</style>
          <header>
            <h1 className="sol-screenreader-only">AI Assistant empty conversation</h1>
          </header>
          <main>
            <SOLAiAssistant open={open} onOpenChange={setOpen} title={args.title} welcomeMessage={args.welcomeMessage} disclaimerMessage={args.disclaimerMessage} width={args.width} resizable={args.resizable} userName={args.userName} messages={messages} suggestions={['Create an AI Agent', 'See what has changed since yesterday', 'How can I manually configure AI Agents?']} moreActions={[{
            id: 'clear',
            label: 'Clear conversation',
            icon: 'sol-delete'
          }, {
            id: 'feedback',
            label: 'Send feedback',
            icon: 'sol-thumbs-up'
          }]} stopEnabled={args.stopEnabled} responding={responding} onStopRequested={() => setResponding(false)} onPromptSubmit={text => {
            setResponding(true);
            setMessages(prev => [...prev, {
              id: `u-${prev.length}`,
              role: 'user',
              content: text
            }, {
              id: `a-${prev.length}`,
              role: 'ai',
              stream: fakeStream('This is a simulated streaming response.', () => setResponding(false))
            }]);
          }} onFeedbackChange={e => console.log('feedbackChange', e)} onRetryRequested={id => console.log('retryRequested', id)} />
          </main>
        </div>
      </div>;
  }
}

