  const handleStepChanged = (step: StepChangedData) => {
    setCurrentStepIndex(step.stepIndex);
  };

  // Marks the current step complete using ordinary React state — replacing the array (not mutating
  // in place) is simply idiomatic React here, not an Angular-OnPush workaround.
  const markCurrentStepComplete = () => {
